{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260921T220951Z/cell-ZXBfV0/src/address.js","content":"/**
 * Cell addresses: 1-2 letters naming a column (A..Z, AA..ZZ) followed by
 * 1-3 digits naming a row of at least 1.
 */

const ADDR_RE = /^([A-Za-z]{1,2})(\d{1,3})$/

/** Converts a column letter run (already 1-2 letters) to its 1-based number. */
function lettersToColumn(letters) {
  const s = letters.toUpperCase()
  let n = 0
  for (const ch of s) {
    n = n * 26 + (ch.charCodeAt(0) - 64)
  }
  return n
}

/** Converts a 1-based column number back to its bijective-base-26 letters. */
export function columnToLetters(n) {
  let s = ''
  let rest = n
  while (rest > 0) {
    const rem = (rest - 1) % 26
    s = String.fromCharCode(65 + rem) + s
    rest = Math.floor((rest - 1) / 26)
  }
  return s
}

/**
 * Parses a raw token into an addressable {col, row} pair, or returns null
 * when the token is not exactly 1-2 letters followed by 1-3 digits naming a
 * row of at least 1 (an out-of-range reference, not a grammar failure).
 */
export function parseAddress(token) {
  const m = ADDR_RE.exec(token)
  if (!m) return null
  const row = parseInt(m[2], 10)
  if (row < 1) return null
  return { col: lettersToColumn(m[1]), row }
}

export function addressToString(addr) {
  return `${columnToLetters(addr.col)}${addr.row}`
}

export function compareAddresses(a, b) {
  if (a.col !== b.col) return a.col - b.col
  return a.row - b.row
}

/** Expands a range between two corners into cells in column-then-row order. */
export function expandRange(a, b) {
  const c0 = Math.min(a.col, b.col)
  const c1 = Math.max(a.col, b.col)
  const r0 = Math.min(a.row, b.row)
  const r1 = Math.max(a.row, b.row)
  const cells = []
  for (let c = c0; c <= c1; c++) {
    for (let r = r0; r <= r1; r++) {
      cells.push({ col: c, row: r })
    }
  }
  return cells
}
"}

