 * Parses the sheet text format: one declaration per line, an address
 * followed by whitespace-separated content, blank lines and `#` comments
 * ignored.
 */

import { parseAddress, addressToString } from './address.js'

const LINE_RE = /^(\S+)(?:[ \t]+(.*))?$/

/**
 * Returns a Map from canonical address string to {addr, content, line}.
 * Throws an Error with a `line` property and a message matching one of the
 * two sheet-parse failure messages the CLI reports.
 */
export function parseSheet(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = new Map()
  lines.forEach((line, idx) => {
    const lineNo = idx + 1
    const stripped = line.replace(/^[ \t]+/, '')
    if (stripped === '' || stripped.startsWith('#')) return

    const m = LINE_RE.exec(stripped)
    const rawAddr = m[1]
    const content = m[2] === undefined ? '' : m[2]

    const addr = parseAddress(rawAddr)
    if (!addr) {
      const err = new Error(`invalid cell address ${rawAddr}`)
      err.line = lineNo
      throw err
    }

    const key = addressToString(addr)
    if (cells.has(key)) {
      const err = new Error(`cell ${key} is declared twice`)
      err.line = lineNo
      throw err
    }

    cells.set(key, { addr, content, line: lineNo })
  })

  return cells
}
"}

