{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260921T220951Z/cell-ZXBfV0/src/lexer.js","content":"/** Tokenizes a formula body (the text after the leading `=`). */

const DIGIT = /[0-9]/
const LETTER = /[A-Za-z]/
const LETTER_OR_DIGIT = /[A-Za-z0-9]/
const SINGLE_PUNCT = '()^*/+-=<>,:'

export class LexError extends Error {}

export function tokenize(src) {
  const tokens = []
  let i = 0
  const n = src.length

  while (i < n) {
    const ch = src[i]
    if (ch === ' ' || ch === '\t') {
      i++
      continue
    }

    if (DIGIT.test(ch)) {
      let j = i + 1
      while (j < n && DIGIT.test(src[j])) j++
      if (src[j] === '.' && DIGIT.test(src[j + 1] || '')) {
        j++
        while (j < n && DIGIT.test(src[j])) j++
      }
      tokens.push({ type: 'number', value: src.slice(i, j) })
      i = j
      continue
    }

    if (LETTER.test(ch)) {
      let j = i + 1
      while (j < n && LETTER_OR_DIGIT.test(src[j])) j++
      tokens.push({ type: 'ident', value: src.slice(i, j) })
      i = j
      continue
    }

    const two = src.slice(i, i + 2)
    if (two === '<=' || two === '>=' || two === '<>') {
      tokens.push({ type: two, value: two })
      i += 2
      continue
    }

    if (SINGLE_PUNCT.includes(ch)) {
      tokens.push({ type: ch, value: ch })
      i++
      continue
    }

    throw new LexError(`unexpected character ${ch}`)
  }

  tokens.push({ type: 'eof', value: '' })
  return tokens
}
"}

