{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260921T220951Z/cell-ZXBfV0/src/parser.js","content":"/**
 * Recursive-descent parser for a formula body, producing an AST.
 *
 * Precedence, loosest to tightest: comparisons, `+ -`, `* /`, `^`, leading
 * sign. Comparisons and the additive/multiplicative operators are
 * left-associative; `^` is right-associative and binds looser than a
 * leading sign, so `-2^2` is `(-2)^2`.
 *
 * A range (`A1:B3`) parses anywhere a cell address could stand, so that a
 * misplaced one still names its cells for `deps`; only a range that is
 * exactly a function call's argument (not wrapped in parentheses or an
 * operator) is marked `direct` and usable by `values`.
 */

import { tokenize } from './lexer.js'

export class ParseError extends Error {}

const COMPARISON_TYPES = new Set(['=', '<>', '<', '<=', '>', '>='])

export function parseFormula(src) {
  const tokens = tokenize(src)
  let pos = 0

  function peek() {
    return tokens[pos]
  }

  function advance() {
    return tokens[pos++]
  }

  function expect(type) {
    if (peek().type !== type) throw new ParseError(`expected ${type}`)
    return advance()
  }

  function parseComparison() {
    let left = parseAdditive()
    while (COMPARISON_TYPES.has(peek().type)) {
      const op = advance().type
      const right = parseAdditive()
      left = { type: 'Binary', op, left, right }
    }
    return left
  }

  function parseAdditive() {
    let left = parseMultiplicative()
    while (peek().type === '+' || peek().type === '-') {
      const op = advance().type
      const right = parseMultiplicative()
      left = { type: 'Binary', op, left, right }
    }
    return left
  }

  function parseMultiplicative() {
    let left = parsePower()
    while (peek().type === '*' || peek().type === '/') {
      const op = advance().type
      const right = parsePower()
      left = { type: 'Binary', op, left, right }
    }
    return left
  }

  function parsePower() {
    const left = parseUnary()
    if (peek().type === '^') {
      advance()
      const right = parsePower()
      return { type: 'Binary', op: '^', left, right }
    }
    return left
  }

  function parseUnary() {
    if (peek().type === '-' || peek().type === '+') {
      const op = advance().type
      const expr = parseUnary()
      return { type: 'Unary', op, expr }
    }
    return parsePrimary()
  }

  function parsePrimary() {
    const t = peek()

    if (t.type === 'number') {
      advance()
