 * Evaluates a sheet's cells lazily, with memoization and cycle detection.
 *
 * A Value is one of:
 *   { k: 'num',  v: number }
 *   { k: 'text', v: string }
 *   { k: 'bool', v: boolean }
 *   { k: 'err',  v: string }   -- one of the error tokens
 */

import { parseAddress, addressToString, expandRange } from './address.js'
import { parseFormula, ParseError } from './parser.js'
import { LexError } from './lexer.js'
import { parseLiteral } from './literal.js'

const VARIADIC = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'])

export function makeEvaluator(sheet) {
  const cache = new Map()
  const visiting = new Set()

  function evalCellByKey(key) {
    if (cache.has(key)) return cache.get(key)
    if (visiting.has(key)) return { k: 'err', v: '#CYCLE!' }

    const entry = sheet.get(key)
    visiting.add(key)
    let result
    if (!entry) {
      result = { k: 'num', v: 0 }
    } else if (entry.content.startsWith('=')) {
      result = evalFormulaCell(entry.content)
    } else {
      result = parseLiteral(entry.content)
    }
    visiting.delete(key)
    cache.set(key, result)
    return result
  }

  function evalFormulaCell(content) {
    let ast
    try {
      ast = parseFormula(content.slice(1))
    } catch (e) {
      if (e instanceof ParseError || e instanceof LexError) return { k: 'err', v: '#ERR!' }
      throw e
    }
    return evalNode(ast)
  }

  function evalNode(node) {
    switch (node.type) {
      case 'Number':
        return { k: 'num', v: node.value }
      case 'Bool':
        return { k: 'bool', v: node.value }
      case 'Paren':
        return evalNode(node.inner)
      case 'Address':
        return evalAddress(node.token)
      case 'Range':
        // Reached only when a range is not directly a function argument.
        return { k: 'err', v: '#ERR!' }
      case 'Unary':
        return evalUnary(node)
      case 'Binary':
        return evalBinary(node)
      case 'Call':
        return evalCall(node)
      default:
        throw new Error(`unknown node type ${node.type}`)
    }
  }

  function evalAddress(token) {
    const addr = parseAddress(token)
    if (!addr) return { k: 'err', v: '#REF!' }
    return evalCellByKey(addressToString(addr))
  }

  function evalUnary(node) {
    const n = toNumber(evalNode(node.expr))
    if (n.k === 'err') return n
    return numResult(node.op === '-' ? -n.v : n.v)
  }

  function evalBinary(node) {
    const left = evalNode(node.left)
    const right = evalNode(node.right)

    if (COMPARISON_OPS.has(node.op)) {
      if (left.k === 'err') return left
      if (right.k === 'err') return right
      return evalCompare(node.op, left, right)
    }

    if (left.k === 'err') return left
    if (right.k === 'err') return right
    const ln = toNumber(left)
    if (ln.k === 'err') return ln
    const rn = toNumber(right)
    if (rn.k === 'err') return rn

    switch (node.op) {
      case '+':
        return numResult(ln.v + rn.v)
      case '-':
        return numResult(ln.v - rn.v)
      case '*':
        return numResult(ln.v * rn.v)
      case '/':
        if (rn.v === 0) return { k: 'err', v: '#DIV/0!' }
        return numResult(ln.v / rn.v)
      case '^':
        return numResult(Math.pow(ln.v, rn.v))
      default:
        throw new Error(`unknown operator ${node.op}`)
    }
  }

  // Expands a direct-range function argument into its cell values, or
  // returns a single #REF! placeholder when either corner is out of range.
  function expandDirectRange(node) {
    const a = parseAddress(node.a)
    const b = parseAddress(node.b)
    if (!a || !b) return [{ k: 'err', v: '#REF!' }]
    return expandRange(a, b).map((c) => evalCellByKey(addressToString(c)))
  }

  // Evaluates a function argument that may be a direct range, flattening it
  // into a list of one or more values (in left-to-right, range-expanded
  // order).
  function flattenArgs(argNodes) {
    const values = []
    for (const arg of argNodes) {
      if (arg.type === 'Range' && arg.direct) {
        values.push(...expandDirectRange(arg))
      } else {
        values.push(evalNode(arg))
