  function evalCall(node) {
    const { name, args } = node

    if (VARIADIC.has(name)) {
      if (args.length < 1) return { k: 'err', v: '#ERR!' }
      return evalVariadic(name, flattenArgs(args))
    }

    if (name === 'ABS') {
      if (args.length !== 1) return { k: 'err', v: '#ERR!' }
      const values = flattenArgs(args)
      for (const v of values) if (v.k === 'err') return v
      const n = toNumber(values[0])
      if (n.k === 'err') return n
      return numResult(Math.abs(n.v))
    }

