 * Walks a formula's AST collecting every distinct in-range cell address it
 * names, ranges expanded, regardless of where in the formula it appears --
 * `deps` is purely syntactic and does not evaluate the formula.
 */

import { parseAddress, addressToString, compareAddresses, expandRange } from './address.js'

export function collectDeps(ast) {
  const found = new Map()

  function addToken(token) {
    const addr = parseAddress(token)
    if (addr) found.set(addressToString(addr), addr)
  }

  function addRange(node) {
    const a = parseAddress(node.a)
    const b = parseAddress(node.b)
    if (!a || !b) return
    for (const c of expandRange(a, b)) found.set(addressToString(c), c)
  }

  function walk(node) {
    switch (node.type) {
      case 'Number':
      case 'Bool':
        return
      case 'Address':
        addToken(node.token)
        return
      case 'Range':
        addRange(node)
        return
      case 'Paren':
        walk(node.inner)
        return
      case 'Unary':
        walk(node.expr)
        return
      case 'Binary':
        walk(node.left)
        walk(node.right)
        return
      case 'Call':
        node.args.forEach(walk)
        return
      default:
        throw new Error(`unknown node type ${node.type}`)
    }
  }

  walk(ast)
  return [...found.values()].sort(compareAddresses)
}
"}

