export function formatValue(v) {
  switch (v.k) {
    case 'num':
      return formatNumber(v.v)
    case 'text':
      return v.v
    case 'bool':
      return v.v ? 'TRUE' : 'FALSE'
    case 'err':
      return v.v
    default:
      throw new Error(`unknown value kind ${v.k}`)
  }
}

function formatNumber(x) {
  return String(roundToSignificantDigits(x, 10))
}

function roundToSignificantDigits(x, sig) {
  if (x === 0 || !Number.isFinite(x)) return x
  const sign = x < 0 ? -1 : 1
  const ax = Math.abs(x)
  const digits = Math.floor(Math.log10(ax)) + 1
  const factor = Math.pow(10, sig - digits)
  return (sign * Math.round(ax * factor)) / factor
}
