/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import fs from 'node:fs'
import { parseSheet } from './sheet.js'
import { parseFormula } from './parser.js'
import { makeEvaluator } from './evaluator.js'
import { collectDeps } from './deps.js'
import { formatValue } from './format.js'
import { compareAddresses, addressToString } from './address.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'values' && mode !== 'deps')) {
    fail('usage: cli.js values|deps')
  }

  const input = fs.readFileSync(0, 'utf8')
  let sheet
  try {
    sheet = parseSheet(input)
  } catch (e) {
    fail(`line ${e.line}: ${e.message}`)
    return
  }

  const entries = [...sheet.values()].sort((a, b) => compareAddresses(a.addr, b.addr))
  const lines = mode === 'values' ? renderValues(sheet, entries) : renderDeps(entries)
  process.stdout.write(lines.map((l) => l + '\n').join(''))
}

function renderValues(sheet, entries) {
  const evaluator = makeEvaluator(sheet)
  return entries.map((entry) => {
    const key = addressToString(entry.addr)
    const value = evaluator.evalCellByKey(key)
    return `${key}=${formatValue(value)}`
  })
}

function renderDeps(entries) {
  return entries.map((entry) => {
    const key = addressToString(entry.addr)
    let deps = []
    if (entry.content.startsWith('=')) {
      try {
        deps = collectDeps(parseFormula(entry.content.slice(1)))
      } catch {
        deps = []
      }
    }
    const rest = deps.map(addressToString).join(' ')
    return rest ? `${key}: ${rest}` : `${key}:`
  })
}

main()
"}

