  })
}

function renderDeps(entries) {
  return entries.map((entry) => {
    const key = addressToString(entry.addr)
    let deps = []
    if (entry.content.startsWith('=')) {
      try {
        deps = collectDeps(parseFormula(entry.content.slice(1)))
      } catch {
        deps = []
      }
    }
    const rest = deps.map(addressToString).join(' ')
    return rest ? `${key}: ${rest}` : `${key}:`
  })
}

main()
